<section class="card" style="margin-top:20px"><div class="section-heading"><h2>Contacts</h2><button class="btn btn-primary" data-open-modal="contact-modal">Add Contact</button></div><div class="table-scroll"><table><thead><tr><th>Name</th><th>Role</th><th>Phone</th><th>Email</th><th>Primary</th></tr></thead><tbody><?php foreach($contacts as $c):?><tr><td><?=e($c['name'])?></td><td><?=e($c['title']?:'—')?></td><td><?php if($c['phone']):?><a href="tel:<?=e(preg_replace('/\D+/','',$c['phone']))?>"><?=e($c['phone'])?></a><?php else:?>—<?php endif;?></td><td><?php if($c['email']):?><a href="mailto:<?=e($c['email'])?>"><?=e($c['email'])?></a><?php else:?>—<?php endif;?></td><td><?=$c['is_primary']?'Yes':'—'?></td></tr><?php endforeach;?></tbody></table></div></section>
